/*
 * Bu sinif altin orani (golden ratio) hesaplayip ekrana basar.
 *
 * Formul: (1 + karekok(5)) / 2
 * Sonuc yaklasik 1.618 civarindadir ve sanat, mimari gibi pek cok
 * alanda karsimiza cikan onemli bir matematiksel sabittir.
 */

public class AltinOran {

	public static void main(String[] args) {

		final double kok5 = Math.sqrt(5);
		final double pay = 1 + kok5;
		final double oran = pay / 2;

		System.out.println("Altin oran: " + oran);
	}
}
