        scanner.close();

        // Siralama algoritmasi (basit karsilastirmalar)
        if (sayi1 > sayi2) { int gecici = sayi1; sayi1 = sayi2; sayi2 = gecici; }
        if (sayi2 > sayi3) { int gecici = sayi2; sayi2 = sayi3; sayi3 = gecici; }
