import java.util.Scanner;

public class AsalSayiKontrolu {

    public static void main(String[] args) {

        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan gecerli bir sayi gelene kadar sormaya devam ediyoruz
        System.out.print("Bir sayi girin: ");
        int deger = okuyucu.nextInt();

        while (deger <= 1) {
            System.out.println("Lutfen 2'den buyuk bir pozitif sayi girin.");
            deger = okuyucu.nextInt();
        }

        okuyucu.close();

        // Asalligi kontrol etmek icin bolen arayan bir yardimci metot cagiriyoruz
        boolean sonuc = asalMi(deger);

        if (sonuc) {
            System.out.println(deger + " asal sayidir.");
        } else {
            System.out.println(deger + " asal sayi degildir.");
        }
    }

    // Verilen sayinin asal olup olmadigini dondurur
    private static boolean asalMi(int sayi) {
        int bolen = 2;
        while (bolen <= sayi / 2) {
            if (sayi % bolen == 0) {
                return false;
            }
            bolen++;
        }
        return true;
    }
}
