import java.util.Scanner;

/*
 * Girilen tam sayinin ciftlik durumu, 2'ye bolumunden kalan uzerinden
 * belirlenir. Kalan sifirsa sayi cift, degilse tektir.
 */

public class TekMiCiftMi {

    public static void main(String[] args) {

        Scanner girdi = new Scanner(System.in);

        System.out.println("Bir sayi giriniz: ");
        int deger = girdi.nextInt();
        girdi.close();

        String durum = (deger % 2 == 0) ? "cift" : "tek";

        System.out.println(deger + " " + durum + " bir sayidir.");
    }
}
