package eamples;

import java.util.Random;
import java.util.Scanner;

public class RastgeleSayiTahmin {

    public static void main(String[] args) {

        Random rng = new Random();
        // Pick the secret target in the inclusive range 1..100.
        int target = rng.nextInt(100) + 1;

        Scanner input = new Scanner(System.in);

        boolean guessedCorrectly = false;

        // Keep asking for guesses until the user lands on the target,
        // using a boolean flag with a while-loop instead of while(true)+break.
        while (!guessedCorrectly) {
            int guess = input.nextInt();

            System.out.println("Rastgele = " + target + " Girilen = " + guess);

            if (guess == target) {
                guessedCorrectly = true;
            } else if (guess < target) {
                System.out.println("Daha buyuk bir sayi giriniz (yukari).");
            } else {
                System.out.println("Daha kucuk bir sayi giriniz (asagi).");
            }
        }

        input.close();
    }
}
