package eamples;

import java.util.Scanner;

public class UsAlma {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Tabani gir:");
        int base = input.nextInt();

        System.out.println("Ussu gir:");
        int exponent = input.nextInt();

        input.close();

        // Multiply the base into the accumulator using a while-loop and a
        // separate countdown variable, instead of the original for-loop.
        int result = 1;
        int remainingMultiplications = exponent;
        while (remainingMultiplications > 0) {
            result = result * base;
            remainingMultiplications--;
        }

        System.out.println(base + "^" + exponent + " = " + result);
    }
}
