package syntax;

public class IsimlendirmeKurallari {

    public static void main(String[] args) {

        // A rundown of legal Java identifiers across the primitive types.
        long phoneNumber;   // valid: simple long variable
        char gender;        // valid: meaningful single-word name
        boolean isMarried;  // valid: meaningful boolean name
        double salaryCalc;  // valid: multi-word, descriptive name
        String fullName;    // valid: identifiers may combine several words
        int age;            // valid: minimal but clear variable name

        // Constants are conventionally written in all caps.
        final double PI_VALUE = 3.14159;

        // Java forbids special characters and whitespace inside identifiers:
        // int 2age;               // invalid: cannot start with a digit
        // String @fullName;       // invalid: cannot start with a special character
        // double salary calc;     // invalid: no spaces allowed
        // boolean is married;     // invalid: no spaces allowed

        // Identifiers should always be descriptive rather than arbitrary.
        String cityName = "Istanbul";
        int studentCount = 100;

        // Identifiers must not start with an uppercase letter by convention:
        // String FullName; // discouraged: should not start with a capital letter

        // camelCase is the standard convention for variable and method names.
        String studentFullName = "Ali Veli";
        double totalSalary = 5000.0;

        // Even so, constant fields are still written in uppercase snake case.
        final int MAX_COUNT = 100;
    }
}
