package syntax;

public class Islecler {

    public static void main(String[] args) {

        int p = 10;
        int q = 20;
        int r = 30;

        // Arithmetic operators
        int addResult = p + q;      // 30
        int subResult = q - p;      // 10
        int mulResult = p * q;      // 200
        int divResult = q / p;      // 2
        int modResult = q % p;      // 0

        // Relational operators
        boolean isEqual = p == q;             // false
        boolean isNotEqual = p != q;          // true
        boolean isGreater = q > p;            // true
        boolean isLess = p < q;               // true
        boolean isGreaterOrEqual = p >= r;    // false
        boolean isLessOrEqual = p <= q;       // true

        // Logical operators
        boolean andResult = (p < q) && (q < r);   // true
        boolean orResult = (p < q) || (q > r);    // true
        boolean notResult = !(p < q);             // false

        // Report every computed value.
        System.out.println("Toplam: " + addResult);
        System.out.println("Fark: " + subResult);
        System.out.println("Carpim: " + mulResult);
        System.out.println("Bolum: " + divResult);
        System.out.println("Kalan: " + modResult);
        System.out.println("esitMi: " + isEqual);
        System.out.println("esitDegilMi: " + isNotEqual);
        System.out.println("buyukMu: " + isGreater);
        System.out.println("kucukMu: " + isLess);
        System.out.println("buyukVeyaEsitMi: " + isGreaterOrEqual);
        System.out.println("kucukVeyaEsitMi: " + isLessOrEqual);
        System.out.println("veSonuc: " + andResult);
        System.out.println("veyaSonuc: " + orResult);
        System.out.println("degilSonuc: " + notResult);
    }
}
