		int yas = 30; // kullaniciyi temsil eden yas bilgisi

		// Degismeyecek bir sabit deger tanimlaniyor
		final double PI = 3.14159; // matematiksel Pi sabiti

		// Metot icinde yerel bir sinif tanimi
		class Ogrenci { // ogrenci bilgilerini tutmak icin kucuk bir yapi
			String ad;
			String soyad;
		}

		// Etiketli dongu kullanimi ornegi
		int sayac = 1;
		disaDongu:
		while (sayac <= 5) {
			if (sayac == 3) {
