package forloop;
import java.util.Scanner;

public class AralikToplama {

    // Iki sinir arasindaki (kucukten buyuge) tum sayilarin toplamini dondurur
    public static void toplaAralik(int alt, int ust) {
        int birikim = 0; // toplami tutan degisken
        int sayac = alt;
        while (sayac <= ust) { // alt sinirdan ust sinira kadar ilerler
            birikim += sayac; // her adimda sayac degeri toplama katilir
            sayac++;
        }
        // Sonucu ekrana bas
        System.out.println(alt + " ile " + ust + " arasindaki sayilarin toplami: " + birikim);
    }

    public static void main(String[] args) {
        Scanner giris = new Scanner(System.in);

        // Kullanicidan ilk siniri al
        System.out.print("Baslangic degerini girin (a): ");
        int deger1 = giris.nextInt();

        // Kullanicidan ikinci siniri al
        System.out.print("Bitis degerini girin (b): ");
        int deger2 = giris.nextInt();

        // Kucuk olan deger once, buyuk olan sonra gelecek sekilde metodu cagir
        if (deger1 < deger2) {
            toplaAralik(deger1, deger2);
        } else {
            toplaAralik(deger2, deger1);
        }

        giris.close();
    }
}
