package forloop;

public class CarpimTablosu {

    public static void main(String[] args) {

        // Tablonun basligini goster
        System.out.println("Carpim Tablosu:");

        // Satirlar icin sayac
        int satir = 1;
        while (satir <= 10) {

            // Sutunlar icin ic dongu
            for (int sutun = 1; sutun <= 10; sutun++) {
                // Iki sayinin carpimini tab karakteriyle hizalayarak yazdir
                System.out.print(satir + "x" + sutun + "=" + (satir * sutun) + "\t");
            }

            // Satir bitince alt satira gec
            System.out.println();
            satir++;
        }
    }
}
