        java.util.Scanner okuyucu = new java.util.Scanner(System.in);
        System.out.print("Toplamak istediginiz sayiyi girin: ");
        int sinir = okuyucu.nextInt();

        int ozelToplam = 0;
        int k = 1;
        while (k <= sinir) {
            ozelToplam += k;
            k++;
        }

        System.out.println("1'den " + sinir + "'a kadar olan sayilarin toplami: " + ozelToplam);

