                // Sayi 35 veya daha buyukse, sayaci bir artir
                otuzbesdenbuyukler++;
            }
        }

        // Sonuclari ekrana yazdir
        System.out.println("\nKucukler: " + otuzbesdenkucukler + 
                           " Buyukler: " + otuzbesdenbuyukler);
