            // 35 esik degeri ile karsilastir
            if (cekilenSayi < 35) {
                esikAltinda++;
            } else {
                esikUstunde++;
            }

            deneme++;
        }

        // Ozet istatistigi yazdir
        System.out.println("\nKucukler: " + esikAltinda +
                           " Buyukler: " + esikUstunde);
    }
