package forloop;

public class SicaklikDonusumu {

    public static void main(String[] args) {

        // Tek bir deger uzerinde donusum yapilir
        {
            double santigrat = 25.0; // baslangic sicakligi (Celsius)
            double fahr = santigrat * 1.8 + 32; // Fahrenheit karsiligi
            double kelvinDeger = santigrat + 273.15; // Kelvin karsiligi

            System.out.println(santigrat + " °C = " + fahr + " °F = " + kelvinDeger + " °K");
        }

        // Birden fazla deger icin donusum toplu yapilir
        {
            double[] listeCelsius = {-40, 0, 25, 100};

            int idx = 0;
            while (idx < listeCelsius.length) {
                double santigrat = listeCelsius[idx];
                double fahr = santigrat * 1.8 + 32;
                double kelvinDeger = santigrat + 273.15;

                System.out.println(santigrat + " °C = " + fahr + " °F = " + kelvinDeger + " °K");
                idx++;
            }
        }
    }
}
