package functions;
import java.util.Scanner;  // kullanicidan sayi almak icin kullanilir

public class BasamakSayisi {

    // Verilen sayinin kac haneli oldugunu hesaplar
    int haneSayisiniHesapla(int deger) {
        int hane = 0; // hane sayacini baslat
        for (; deger > 0; deger /= 10) {
            // her bolme islemi bir haneyi temsil eder
            hane++;
        }
        return hane;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);
        int girilenDeger = tarayici.nextInt();

        BasamakSayisi hesaplayici = new BasamakSayisi();

        // Hane sayisini hesapla ve yazdir
        int hane = hesaplayici.haneSayisiniHesapla(girilenDeger);
        System.out.println(hane);

        tarayici.close();
    }
}
