package functions;
import java.util.Scanner;  // kullanicidan girdi okumak icin

public class Faktoriyel {

    // Verilen sayinin faktoriyelini hesaplayip dondurur
    int faktoriyelHesapla(int deger) {
        int carpim = 1; // notr eleman ile baslatilir
        for (; deger > 0; deger--) {
            carpim *= deger; // her adimda mevcut degerle carpilir
        }
        return carpim;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz");
        int girilenDeger = tarayici.nextInt();

        Faktoriyel hesaplayici = new Faktoriyel();

        int sonuc = hesaplayici.faktoriyelHesapla(girilenDeger);
        System.out.println("Sonuc = " + sonuc);

        tarayici.close();
    }
}
