package functions;

public class SayiOkuma {

    public static void main(String[] args) {

        System.out.println(sayiyiYaziyaCevir(1234)); // ornek degerlerin yazili karsiligini goster

        System.out.println(sayiyiYaziyaCevir(7248));

        System.out.println(sayiyiYaziyaCevir(297));

        System.out.println(sayiyiYaziyaCevir(505));

        System.out.println(sayiyiYaziyaCevir(300));
    }

    // Verilen dort haneye kadar olan sayiyi Turkce yaziya cevirir
    public static String sayiyiYaziyaCevir(int deger) {
        if (deger == 0) {
            return "sifir";
        }

        StringBuilder metin = new StringBuilder();

        int binler = deger / 1000;
        int yuzler = (deger / 100) % 10;
        int onlar = (deger / 10) % 10;
        int birler = deger % 10;

        if (binler > 0) {
            metin.append(binHanesiYaz(binler)).append(" ");
        }
        if (yuzler > 0) {
            metin.append(yuzHanesiYaz(yuzler)).append(" ");
        }
        if (onlar > 0) {
            metin.append(onlarHanesiYaz(onlar)).append(" ");
        }
        if (birler > 0) {
            metin.append(birlerHanesiYaz(birler));
        }

        return metin.toString().trim();
    }

    // Binler hanesinin karsiligini switch yapisiyla belirler
    public static String binHanesiYaz(int binler) {
        switch (binler) {
            case 1: return "bin";
            case 2: return "iki bin";
            case 3: return "uc bin";
            case 4: return "dort bin";
            case 5: return "bes bin";
            case 6: return "alti bin";
            case 7: return "yedi bin";
            case 8: return "sekiz bin";
            case 9: return "dokuz bin";
            default: return "";
        }
    }

    // Yuzler hanesinin karsiligini switch yapisiyla belirler
    public static String yuzHanesiYaz(int yuzler) {
        switch (yuzler) {
            case 1: return "yuz";
            case 2: return "iki yuz";
            case 3: return "uc yuz";
            case 4: return "dort yuz";
            case 5: return "bes yuz";
            case 6: return "alti yuz";
            case 7: return "yedi yuz";
            case 8: return "sekiz yuz";
            case 9: return "dokuz yuz";
            default: return "";
        }
    }

    // Onlar hanesinin karsiligini switch yapisiyla belirler
    public static String onlarHanesiYaz(int onlar) {
        switch (onlar) {
            case 1: return "on";
            case 2: return "yirmi";
            case 3: return "otuz";
            case 4: return "kirk";
            case 5: return "elli";
            case 6: return "altmis";
            case 7: return "yetmis";
            case 8: return "seksen";
            case 9: return "doksan";
            default: return "";
        }
    }

    // Birler hanesinin karsiligini switch yapisiyla belirler
    public static String birlerHanesiYaz(int birler) {
        switch (birler) {
            case 1: return "bir";
            case 2: return "iki";
            case 3: return "uc";
            case 4: return "dort";
            case 5: return "bes";
            case 6: return "alti";
            case 7: return "yedi";
            case 8: return "sekiz";
            case 9: return "dokuz";
            default: return "";
        }
    }
}
