 */

public class BurcYazdirma {

	// Ay ve gune gore ilgili burc adini hesaplayan yardimci metod
	private static String burcBul(int ay, int gun) {
		if ((ay == 3 && gun >= 21) || (ay == 4 && gun <= 19)) {
			return "Koc";
		}
		if ((ay == 4 && gun >= 20) || (ay == 5 && gun <= 20)) {
			return "Boga";
		}
		if ((ay == 5 && gun >= 21) || (ay == 6 && gun <= 20)) {
			return "ikizler";
		}
		if ((ay == 6 && gun >= 21) || (ay == 7 && gun <= 22)) {
			return "Yengec";
		}
		if ((ay == 7 && gun >= 23) || (ay == 8 && gun <= 22)) {
			return "Aslan";
		}
		if ((ay == 8 && gun >= 23) || (ay == 9 && gun <= 22)) {
			return "Basak";
		}
		if ((ay == 9 && gun >= 23) || (ay == 10 && gun <= 22)) {
			return "Terazi";
		}
		if ((ay == 10 && gun >= 23) || (ay == 11 && gun <= 21)) {
			return "Akrep";
		}
		if ((ay == 11 && gun >= 22) || (ay == 12 && gun <= 21)) {
			return "Yay";
		}
		if ((ay == 12 && gun >= 22) || (ay == 1 && gun <= 19)) {
			return "Oglak";
		}
		if ((ay == 1 && gun >= 20) || (ay == 2 && gun <= 18)) {
			return "Kova";
		}
		if ((ay == 2 && gun >= 19) || (ay == 3 && gun <= 20)) {
			return "Balik";
		}
