package recursive;
import java.util.Scanner;

public class EnBuyukOrtakBolen {

	// Iki sayinin ortak bolenlerinin en buyugunu Oklid algoritmasiyla hesaplar
	public static int ortakBolenBul(int birinci, int ikinci) {
		int x = birinci;
		int y = ikinci;
		// ikinci deger sifira dusene kadar kalanla islem tekrarlanir
		while (y != 0) {
			int kalan = x % y;
			x = y;
			y = kalan;
		}
		return x;
	}

	public static void main(String[] args) {

		Scanner tarayici = new Scanner(System.in);
		System.out.print("Ebobu bulmak icin bir sayi girin: ");
		int ilkSayi = tarayici.nextInt();
		System.out.print("Ebob bulmak icin bir sayi daha girin: ");
		int ikinciSayi = tarayici.nextInt();
		tarayici.close();

		int ebobSonucu = ortakBolenBul(ilkSayi, ikinciSayi);
		System.out.print("En buyuk ortak bolen: " + ebobSonucu);
	}
}
