package recursive;
import java.util.Scanner;

public class Faktoriyel {

	// Ozyineleme kullanarak faktoriyeli hesaplar
	public static int ozyinelemeliFaktoriyel(int deger) {
		// Taban durum: 0'in faktoriyeli 1 kabul edilir
		if (deger == 0) {
			return 1;
		}
		// Genel durum: deger ile bir onceki degerin faktoriyeli carpilir
		return deger * ozyinelemeliFaktoriyel(deger - 1);
	}

	// Dongu kullanarak faktoriyeli hesaplar
	public static int donguluFaktoriyel(int deger) {
		int carpim = 1;
		int i = 1;
		// i, degere ulasana kadar carpima katilir
		while (i <= deger) {
			carpim *= i;
			i++;
		}
		return carpim;
	}

	public static void main(String[] args) {

		Scanner tarayici = new Scanner(System.in);
		System.out.print("Faktoriyelini hesaplamak icin bir sayi girin: ");
		int girilenSayi = tarayici.nextInt();
		tarayici.close();

		System.out.println(girilenSayi + " sayisinin faktoriyeli (iterative): " + donguluFaktoriyel(girilenSayi));
		System.out.println(girilenSayi + " sayisinin faktoriyeli (rekursive): " + ozyinelemeliFaktoriyel(girilenSayi));
	}
}
