package whileloop;

public class KarekokBulma {

	// Ikili arama (binary search) yontemiyle bir sayinin karekokune yaklasik olarak ulasir
	public static double karekokTahminEt(double hedefSayi) {
		double altSinir = 0.0;
		double ustSinir = hedefSayi;
		final double hassasiyet = 0.00001;

		while ((ustSinir - altSinir) > hassasiyet) {
			double ortancaDeger = (altSinir + ustSinir) / 2;
			double ortancaninKaresi = ortancaDeger * ortancaDeger;

			if (ortancaninKaresi > hedefSayi) {
				ustSinir = ortancaDeger;
			} else {
				altSinir = ortancaDeger;
			}
		}

		return (altSinir + ustSinir) / 2;
	}

	public static void main(String[] args) {
		double[] denemeDegerleri = {10.0, 16.0, 100.0};

		for (double deger : denemeDegerleri) {
			double sonuc = karekokTahminEt(deger);
			System.out.println(deger + " sayisinin karekoku: " + sonuc);
		}
	}
}
