package encapsulation;

/*
 * Represents a customer's bank account.
 * Wraps the account number, balance and account category behind
 * private fields, exposing only controlled operations.
 */
public class BankaHesabi {

	private int accountId;
	private double currentBalance;
	private String accountCategory; // e.g. "Vadesiz" (checking) or "Vadeli" (term deposit)

	public BankaHesabi(int accountId, double currentBalance, String accountCategory) {
		this.accountId = accountId;
		this.currentBalance = currentBalance;
		this.accountCategory = accountCategory;
	}

	public int getHesapNumarasi() {
		return accountId;
	}

	public double getBakiye() {
		return currentBalance;
	}

	public String getHesapTuru() {
		return accountCategory;
	}

	/**
	 * Deposits funds into the account, rejecting non-positive amounts.
	 */
	public void paraYatir(double amount) {
		boolean isValid = amount > 0;
		if (isValid) {
			currentBalance = currentBalance + amount;
			System.out.println(amount + " TL yatirildi. Yeni bakiye: " + currentBalance);
		} else {
			System.out.println("Yatirilan miktar gecersiz.");
		}
	}

	/**
	 * Withdraws funds, checking both validity and sufficient balance.
	 */
	public void paraCek(double amount) {
		if (amount > 0 && amount <= currentBalance) {
			currentBalance = currentBalance - amount;
			System.out.println(amount + " TL cekildi. Kalan bakiye: " + currentBalance);
		} else if (amount > currentBalance) {
			System.out.println("Yetersiz bakiye.");
		} else {
			System.out.println("cekilen miktar gecersiz.");
		}
	}

	/**
	 * Applies interest only when the account is a term ("Vadeli") account.
	 */
	public void faizEkle(double rate) {
		boolean isTermAccount = accountCategory.equals("Vadeli");
		if (isTermAccount && rate > 0) {
			double interestAmount = currentBalance * rate / 100;
			currentBalance += interestAmount;
			System.out.println("Faiz ekleniyor: " + interestAmount + " TL. Yeni bakiye: " + currentBalance);
		} else if (!isTermAccount) {
			System.out.println("Faiz yalnizca vadeli hesaplarda uygulanabilir.");
		} else {
			System.out.println("Gecersiz faiz orani.");
		}
	}

	/**
	 * Moves money from this account into another BankaHesabi instance.
	 */
	public void transfer(BankaHesabi receivingAccount, double amount) {
		if (amount > 0 && amount <= currentBalance) {
			currentBalance -= amount;
			receivingAccount.paraYatir(amount);
			System.out.println(amount + " TL transfer edildi. Yeni bakiye: " + currentBalance);
		} else {
			System.out.println("Yetersiz bakiye veya gecersiz miktar.");
		}
	}
}
