package objects;

/*
 * Models a rectangle with width and height, capable of computing
 * area, perimeter and diagonal (hypotenuse) length.
 */
public class Dikdortgen {

	private double boyutUzun;   // the rectangle's length
	private double boyutKisa;   // the rectangle's width

	public Dikdortgen(double boyutUzun, double boyutKisa) {
		this.boyutUzun = boyutUzun;
		this.boyutKisa = boyutKisa;
	}

	// Returns length * width.
	public double alanHesapla() {
		return boyutUzun * boyutKisa;
	}

	// Returns 2 * (length + width).
	public double cevreHesapla() {
		return 2 * (boyutUzun + boyutKisa);
	}

	// Replaces the current dimensions with new ones.
	public void alanGuncelle(double yeniBoyutUzun, double yeniBoyutKisa) {
		this.boyutUzun = yeniBoyutUzun;
		this.boyutKisa = yeniBoyutKisa;
	}

	@Override
	public String toString() {
		return "Uzunluk: " + boyutUzun + ", Genislik: " + boyutKisa + ", Alan: " + alanHesapla() + ", Cevre: " + cevreHesapla();
	}

	public static void main(String[] args) {

		Dikdortgen sekilBir = new Dikdortgen(10.0, 5.0);
		Dikdortgen sekilIki = new Dikdortgen(3.0, 7.0);
		Dikdortgen kareSekli = new Dikdortgen(4.0, 4.0); // a square is just a rectangle with equal sides

		System.out.println("Dikdortgen 1: " + sekilBir);
		System.out.println("Dikdortgen 2: " + sekilIki);
		System.out.println("Kare: " + kareSekli);

		sekilBir.alanGuncelle(12.0, 6.0);
		System.out.println("Guncellenmis Dikdortgen 1: " + sekilBir);

		double kosegenBir = sekilBir.hipotenusHesapla();
		double kosegenIki = sekilIki.hipotenusHesapla();
		double kosegenKare = kareSekli.hipotenusHesapla();

		System.out.println("Dikdortgen 1'in Hipotenusu: " + kosegenBir);
		System.out.println("Dikdortgen 2'nin Hipotenusu: " + kosegenIki);
		System.out.println("Karenin Hipotenusu: " + kosegenKare);

		if (sekilBir.alanHesapla() > sekilIki.alanHesapla()) {
			System.out.println("Dikdortgen 1'in alani, Dikdortgen 2'den buyuktur.");
		} else if (sekilBir.alanHesapla() < sekilIki.alanHesapla()) {
			System.out.println("Dikdortgen 2'nin alani, Dikdortgen 1'den buyuktur.");
		} else {
			System.out.println("Dikdortgen 1 ve Dikdortgen 2'nin alanlari esittir.");
		}
	}

	// Uses the Pythagorean theorem to compute the diagonal length.
	public double hipotenusHesapla() {
		return Math.sqrt(Math.pow(boyutUzun, 2) + Math.pow(boyutKisa, 2));
	}
}
