import java.util.ArrayList;
import java.util.List;

/*
 * Tracks a student's enrolled courses and their corresponding
 * grades, and can report a pass/fail status from the average.
 */
public class Ogrenci {

    private String ogrenciAdi;
    private int ogrenciNo;
    private List<String> kayitliDersler;
    private List<Double> alinanNotlar;

    public Ogrenci(String ogrenciAdi, int ogrenciNo) {
        this.ogrenciAdi = ogrenciAdi;
        this.ogrenciNo = ogrenciNo;
        this.kayitliDersler = new ArrayList<>();
        this.alinanNotlar = new ArrayList<>();
    }

    // Introduces the student by name and number.
    public void selamVer() {
        System.out.println("Merhaba, ben " + this.ogrenciAdi + ". Numaram: " + this.ogrenciNo);
    }

    // Registers a course along with its grade.
    public void dersEkle(String dersAdi, double alinanNot) {
        kayitliDersler.add(dersAdi);
        alinanNotlar.add(alinanNot);
        System.out.println(dersAdi + " dersi ve " + alinanNot + " notu eklendi.");
    }

    // Computes the grade average and reports pass/fail (threshold 60).
    public void basariDurumu() {
        double toplamPuan = 0;
        for (double tekNot : alinanNotlar) {
            toplamPuan += tekNot;
        }
        double ortalamaPuan = toplamPuan / alinanNotlar.size();

        System.out.println(ogrenciAdi + " adli ogrencinin not ortalamasi: " + ortalamaPuan);

        if (ortalamaPuan >= 60) {
            System.out.println(ogrenciAdi + " basarili.");
        } else {
            System.out.println(ogrenciAdi + " basarisiz.");
        }
    }

    // Lists every registered course next to its grade.
    public void dersleriYazdir() {
        System.out.println(ogrenciAdi + " adli ogrencinin dersleri ve notlari:");
        for (int index = 0; index < kayitliDersler.size(); index++) {
            System.out.println(kayitliDersler.get(index) + " - Not: " + alinanNotlar.get(index));
        }
    }

    @Override
    public String toString() {
        return "Ogrenci [ad=" + ogrenciAdi + ", numara=" + ogrenciNo + ", dersler=" + kayitliDersler + ", notlar=" + alinanNotlar + "]";
    }

    public static void main(String[] args) {

        Ogrenci birinciOgrenci = new Ogrenci("Ali", 20122273);
        Ogrenci ikinciOgrenci = new Ogrenci("Ayse", 20132272);

        birinciOgrenci.dersEkle("Matematik", 75.0);
        birinciOgrenci.dersEkle("Fizik", 82.0);
        birinciOgrenci.dersEkle("Kimya", 90.0);

        ikinciOgrenci.dersEkle("Matematik", 65.0);
        ikinciOgrenci.dersEkle("Fizik", 58.0);
        ikinciOgrenci.dersEkle("Kimya", 72.0);

        birinciOgrenci.selamVer();
        ikinciOgrenci.selamVer();

        birinciOgrenci.dersleriYazdir();
        ikinciOgrenci.dersleriYazdir();

        birinciOgrenci.basariDurumu();
        ikinciOgrenci.basariDurumu();

        System.out.println(birinciOgrenci);
        System.out.println(ikinciOgrenci);
    }
}
