import java.awt.Color;
import java.awt.Rectangle;

/*
 * Common blueprint for every enemy vehicle that descends
 * down the play field. Concrete subclasses only differ in
 * size, colour and descent speed.
 */
public class Tank {

    Rectangle bounds;   // position + size on screen
    Color renk;
    int hiz;            // pixels moved per tick

    public Tank(int x, int y, int genislik, int yukseklik, Color renk, int hiz) {
        this.bounds = new Rectangle(x, y, genislik, yukseklik);
        this.renk = renk;
        this.hiz = hiz;
    }

    public void hareketEt() {
        // Push the vehicle further down the screen each frame.
        bounds.y = bounds.y + hiz;
    }
}
