package tankgame;

import java.awt.Color;

/*
 * Abstract player-controlled defense turret. Holds shared
 * geometry/colour state; each concrete turret decides what
 * kind of shell it fires.
 */
public abstract class Tanksavar {

    private static final int VARSAYILAN_GENISLIK = 40;
    private static final int VARSAYILAN_YUKSEKLIK = 30;

    int x, y;
    int genislik, yukseklik;
    Color renk;
    Top top;

    protected Tanksavar(int x, int y, Color renk) {
        this.x = x;
        this.y = y;
        this.genislik = VARSAYILAN_GENISLIK;
        this.yukseklik = VARSAYILAN_YUKSEKLIK;
        this.renk = renk;
    }

    // Produces the projectile this turret shoots.
    public abstract Top topAt();
}
