package array;

public class EnKucukElemaniBul {

    public static void main(String[] args) {
        // Test amacli sabit degerler
        int[] veriSeti = {5, 2, 8, 1, 9, 4, 7};

        int enKucuk = bulEnKucugu(veriSeti);

        System.out.println("Dizideki Minimum Eleman: " + enKucuk);
    }

    // Diziyi bastan sona tarayarak en dusuk degeri dondurur
    private static int bulEnKucugu(int[] degerler) {
        int aday = degerler[0];

        int indeks = degerler.length - 1;
        while (indeks >= 1) {
            if (degerler[indeks] < aday) {
                aday = degerler[indeks];
            }
            indeks--;
        }

        return aday;
    }
}
