        for (int i = 0; i < dizi.length - 1; i++) {
            // Siralama islemi icin tekrar et
            for (int j = 0; j < dizi.length - i - 1; j++) {
                if (dizi[j] > dizi[j + 1]) {
                    // Elemanlari yer degistir
                    int gecici = dizi[j];
                    dizi[j] = dizi[j + 1];
                    dizi[j + 1] = gecici;
                }
            }
        }
    }
}
