package array;

public class KabarcikSiralama {

    public static void main(String[] args) {

        int[] veriler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        kabarcikYontemiUygula(veriler);

        System.out.println("Siralanmis Dizi:");
        StringBuilder cikti = new StringBuilder();
        for (int deger : veriler) {
            cikti.append(deger).append(' ');
        }
        System.out.print(cikti);
    }

    // Bubble sort - komsu elemanlari kiyaslayip gerekince yer degistirir
    static void kabarcikYontemiUygula(int[] veriler) {
        int boyut = veriler.length;
        boolean degisiklikOldu;

        int tur = 0;
        do {
            degisiklikOldu = false;
            for (int k = 0; k < boyut - 1 - tur; k++) {
                if (veriler[k] > veriler[k + 1]) {
                    int gecici = veriler[k];
                    veriler[k] = veriler[k + 1];
                    veriler[k + 1] = gecici;
                    degisiklikOldu = true;
                }
            }
            tur++;
        } while (degisiklikOldu && tur < boyut - 1);
    }
}
