package array;

public class SecmeliSiralama {

    public static void main(String[] args) {
        int[] degerler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        siralamayiUygula(degerler);

        System.out.println("Siralanmis Dizi:");
        StringBuilder cikti = new StringBuilder();
        for (int deger : degerler) {
            cikti.append(deger).append(' ');
        }
        System.out.print(cikti);
    }

    // Selection sort - her turda kalan en kucuk elemani one tasir
    public static void siralamayiUygula(int[] degerler) {
        int uzunluk = degerler.length;

        for (int sinir = 0; sinir < uzunluk - 1; sinir++) {
            int enKucukKonum = sinir;

            for (int arayan = sinir + 1; arayan < uzunluk; arayan++) {
                if (degerler[arayan] < degerler[enKucukKonum]) {
                    enKucukKonum = arayan;
                }
            }

            if (enKucukKonum != sinir) {
                int gecici = degerler[sinir];
                degerler[sinir] = degerler[enKucukKonum];
                degerler[enKucukKonum] = gecici;
            }
        }
    }
}
