package collections;

import java.util.ArrayList;
import java.util.List;

public class Fibonacci {

    // n. Fibonacci sayisini asagidan yukariya (iteratif) hesaplar
    public static int fibonacci(int n) {
        List<Integer> hesaplananlar = new ArrayList<>();
        hesaplananlar.add(0);
        hesaplananlar.add(1);

        int sayac = 2;
        while (sayac <= n) {
            int oncekiIki = hesaplananlar.get(sayac - 2);
            int oncekiBir = hesaplananlar.get(sayac - 1);
            hesaplananlar.add(oncekiIki + oncekiBir);
            sayac++;
        }

        return hesaplananlar.get(n);
    }

    public static void main(String[] args) {
        int hedefIndeks = 10;
        int deger = fibonacci(hedefIndeks);
        System.out.println(deger);
    }
}
