package collections;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Loto {

    // Havuzdaki sayilari karistirip istenen adette cekilis yapar
    public static Integer[] cekilisYap(int havuzBuyuklugu, int kacTaneCekilecek) {
        List<Integer> havuz = new ArrayList<>();

        for (int deger = 1; deger <= havuzBuyuklugu; deger++) {
            havuz.add(deger);
        }

        Collections.shuffle(havuz);

        Integer[] secilenler = new Integer[kacTaneCekilecek];
        for (int i = 0; i < kacTaneCekilecek; i++) {
            secilenler[i] = havuz.get(i);
        }

        return secilenler;
    }

    public static void main(String[] args) {
        Integer[] cekilenNumaralar = cekilisYap(49, 6);

        StringBuilder cikti = new StringBuilder();
        for (Integer numara : cekilenNumaralar) {
            cikti.append(numara).append(' ');
        }
        System.out.print(cikti);
    }
}
