package string;

import java.util.Random;

/*
 * Uzunlugu 8 ile 12 karakter arasinda degisen rastgele bir sifre uretir.
 * Uretilen sifre en az bir buyuk harf, bir rakam ve bir sembol icerir.
 */

public class SifreUreteci {

    private static final String BUYUK_HARFLER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String RAKAMLAR = "0123456789";
    private static final String SEMBOLLER = "!@#$%^&*()_+-=[]{}|;':\"<>,.?/\\";

    public static String yeniSifreOlustur() {
        Random rng = new Random();

        int hedefUzunluk = 8 + rng.nextInt(5);

        StringBuilder tampon = new StringBuilder();
        tampon.append(BUYUK_HARFLER.charAt(rng.nextInt(BUYUK_HARFLER.length())));
        tampon.append(RAKAMLAR.charAt(rng.nextInt(RAKAMLAR.length())));
        tampon.append(SEMBOLLER.charAt(rng.nextInt(SEMBOLLER.length())));

        String genelHavuz = BUYUK_HARFLER + RAKAMLAR + SEMBOLLER + BUYUK_HARFLER.toLowerCase();
        for (int kalan = hedefUzunluk - 3; kalan > 0; kalan--) {
            tampon.append(genelHavuz.charAt(rng.nextInt(genelHavuz.length())));
        }

        return harfleriKaristir(tampon.toString());
    }

    public static String harfleriKaristir(String girdi) {
        char[] harfler = girdi.toCharArray();
        Random rng = new Random();

        for (int son = harfler.length - 1; son > 0; son--) {
            int hedefIndeks = rng.nextInt(son);
            char gecici = harfler[hedefIndeks];
            harfler[hedefIndeks] = harfler[son];
            harfler[son] = gecici;
        }

        return new String(harfler);
    }

    public static void main(String[] args) {
        System.out.println(yeniSifreOlustur());
    }
}
