package twodimensional;

import java.util.Random;

/*
 * Randomized maze generator.
 *
 * This class fills a 2D grid with either wall cells ('#') or open path
 * cells ('.') using a simple probability check for each position, then
 * prints the resulting grid to standard output.
 */

public class Labirent {

    private static final int COLUMN_COUNT = 10;      // how many columns the grid has
    private static final int ROW_COUNT = 10;          // how many rows the grid has
    private static final char WALL_SYMBOL = '#';       // symbol used for blocked cells
    private static final char PATH_SYMBOL = '.';       // symbol used for open cells
    private static final double WALL_CHANCE = 0.3;     // probability a cell becomes a wall

    private static char[][] grid; // holds the generated maze layout

    public static void main(String[] args) {
        grid = buildRandomGrid();
        renderGrid();
    }

    // Builds a grid where each cell is randomly chosen to be a wall or a path.
    private static char[][] buildRandomGrid() {
        Random randomizer = new Random();
        char[][] freshGrid = new char[ROW_COUNT][COLUMN_COUNT];

        for (int row = 0; row < ROW_COUNT; row++) {
            for (int col = 0; col < COLUMN_COUNT; col++) {
                boolean isWall = randomizer.nextDouble() < WALL_CHANCE;
                freshGrid[row][col] = isWall ? WALL_SYMBOL : PATH_SYMBOL;
            }
        }

        return freshGrid;
    }

    // Prints every row of the grid, separating cells with a single space.
    private static void renderGrid() {
        StringBuilder lineBuffer;
        for (int row = 0; row < ROW_COUNT; row++) {
            lineBuffer = new StringBuilder();
            for (int col = 0; col < COLUMN_COUNT; col++) {
                lineBuffer.append(grid[row][col]).append(' ');
            }
            System.out.println(lineBuffer.toString().trim());
        }
    }
}
