// Computes the product of two square integer matrices.
package twodimensional;

public class MatrisCarpimi {

    public static void main(String[] args) {
        // Left-hand operand matrix
        int[][] left = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };

        // Right-hand operand matrix
        int[][] right = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int leftRows = left.length;        // number of rows in the left matrix
        int leftCols = left[0].length;      // number of columns in the left matrix
        int rightCols = right[0].length;    // number of columns in the right matrix

        int[][] product = new int[leftRows][rightCols];

        // Standard triple-nested-loop matrix multiplication
        for (int row = 0; row < leftRows; row++) {
            for (int col = 0; col < rightCols; col++) {
                int accumulator = 0;
                for (int k = 0; k < leftCols; k++) {
                    accumulator += left[row][k] * right[k][col];
                }
                product[row][col] = accumulator;
            }
        }

        System.out.println("Matris Carpim Sonucu:");
        printMatrix(product);
    }

    // Helper that prints a matrix row by row, space separated.
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int value : row) {
                sb.append(value).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}
