public class ChatSunucu {

    public static void main(String[] args) throws IOException {
        try (ServerSocket listener = new ServerSocket(8000)) {
            System.out.println("Sunucu baslatildi");

            // Block until a client connects
            Socket client = listener.accept();

            System.out.println("Istemci baglandi");

            DataInputStream fromClient = new DataInputStream(client.getInputStream());
            DataOutputStream toClient = new DataOutputStream(client.getOutputStream());

            while (true) {
                String message = fromClient.readUTF();
                toClient.writeUTF(message); // simple echo back to the client
            }
        }
    }
