import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

/*
 * Reads arithmetic expressions line by line from "islemler.txt". Each line
 * holds two numbers and an operator separated by spaces; the computed
 * result for each line is printed to the console.
 */

public class HesapMakinesi {

    public static void main(String[] args) {

        try {
            BufferedReader lineSource = new BufferedReader(new FileReader("islemler.txt"));
            String line;

            while ((line = lineSource.readLine()) != null) {
                String[] tokens = line.split(" ");
                int operandA = Integer.parseInt(tokens[0]);
                int operandB = Integer.parseInt(tokens[2]);
                char operator = tokens[1].charAt(0);
                int result;

                switch (operator) {
                    case '+':
                        result = operandA + operandB;
                        break;
                    case '-':
                        result = operandA - operandB;
                        break;
                    case '*':
                        result = operandA * operandB;
                        break;
                    case '/':
                        if (operandB == 0) {
                            System.out.println("Hata: Sifira bolme yapilamaz!");
                            continue; // skip printing, move to the next line
                        }
                        result = operandA / operandB;
                        break;
                    default:
                        result = 0;
                        break;
                }

                System.out.println(operandA + " " + operator + " " + operandB + " = " + result);
            }

            lineSource.close();
        } catch (IOException fileEx) {
            System.out.println("Dosya okunurken bir hata olustu: " + fileEx.getMessage());
        } catch (NumberFormatException parseEx) {
            System.out.println("Sayilari parse ederken bir hata olustu: " + parseEx.getMessage());
        }
    }
}
