import java.io.*;

/*
 * Kucuk bir gosterim: Personel adli sinif Serializable'i implemente eder,
 * boylece bir nesne ObjectOutputStream araciligiyla diske yazilabilir
 * (serialize) ve sonrasinda ObjectInputStream ile geri okunabilir
 * (deserialize). Geri okunan nesne, yazilan nesneyle ayni alan degerlerine
 * sahip olmalidir.
 */

public class Serilestirme {

    private static final String DOSYA_ADI = "calisan.ser";

    public static void main(String[] args) {
        Personel orijinal = new Personel("Ahmet Yilmaz", 54321, "Yazilim Muhendisi");

        diskeYaz(orijinal);

        Personel okunan = diskeninOku();
        if (okunan == null) {
            return;
        }

        System.out.println("Geri Yuklenen Calisan...");
        System.out.println("Isim: " + okunan.adiniGetir());
        System.out.println("ID: " + okunan.numarasiniGetir());
        System.out.println("Unvan: " + okunan.unvaniniGetir());
    }

    private static void diskeYaz(Personel p) {
        try (FileOutputStream fos = new FileOutputStream(DOSYA_ADI);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {
            oos.writeObject(p);
            System.out.println("Calisan nesnesi " + DOSYA_ADI + " dosyasina serilestirildi.");
        } catch (IOException hata) {
            hata.printStackTrace();
        }
    }

    private static Personel diskeninOku() {
        try (FileInputStream fis = new FileInputStream(DOSYA_ADI);
             ObjectInputStream ois = new ObjectInputStream(fis)) {
            return (Personel) ois.readObject();
        } catch (IOException hata) {
            hata.printStackTrace();
            return null;
        } catch (ClassNotFoundException hata) {
            System.out.println("Calisan sinifi bulunamadi.");
            hata.printStackTrace();
            return null;
        }
    }
}

/** Basit, serilestirilebilir bir personel kaydi. */
class Personel implements Serializable {

    private static final long serialVersionUID = 1L;

    private final String ad;
    private final int sicilNo;
    private final String pozisyon;

    public Personel(String ad, int sicilNo, String pozisyon) {
        this.ad = ad;
        this.sicilNo = sicilNo;
        this.pozisyon = pozisyon;
    }

    public String adiniGetir() {
        return ad;
    }

    public int numarasiniGetir() {
        return sicilNo;
    }

    public String unvaniniGetir() {
        return pozisyon;
    }
}
