import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;

/**
 * Walks a directory tree and strips Turkish-specific accented letters
 * out of every ".java" source file it finds (except files starting
 * with "Turkce"), replacing them with their plain ASCII equivalents.
 */
public class TurkceKarakterDegistirici {

    private static final Map<String, String> DEGISIM_TABLOSU = new LinkedHashMap<>();
    static {
        DEGISIM_TABLOSU.put("ü", "u");
        DEGISIM_TABLOSU.put("Ü", "U");
        DEGISIM_TABLOSU.put("ğ", "g");
        DEGISIM_TABLOSU.put("Ğ", "G");
        DEGISIM_TABLOSU.put("ı", "i");
        DEGISIM_TABLOSU.put("İ", "I");
        DEGISIM_TABLOSU.put("ş", "s");
        DEGISIM_TABLOSU.put("Ş", "S");
        DEGISIM_TABLOSU.put("ç", "c");
        DEGISIM_TABLOSU.put("Ç", "C");
        DEGISIM_TABLOSU.put("ö", "o");
        DEGISIM_TABLOSU.put("Ö", "O");
    }

    /** Belirtilen klasoru ve tum alt klasorlerini gezerek uygun dosyalari isler. */
    public static void agaciGez(File baslangicNoktasi) {
        File[] icerik = baslangicNoktasi.listFiles();
        if (icerik == null) {
            return;
        }

        for (File oge : icerik) {
            if (oge.isDirectory()) {
                agaciGez(oge);
            } else if (isleneceklerdenMi(oge)) {
                dosyayiTemizle(oge);
            }
        }
    }

    private static boolean isleneceklerdenMi(File oge) {
        return oge.isFile()
                && oge.getName().endsWith(".java")
                && !oge.getName().startsWith("Turkce");
    }

    /** Bir Java dosyasindaki Turkce karakterleri ayiklayip degisiklikleri diske yansitir. */
    private static void dosyayiTemizle(File hedefDosya) {
        try {
            List<String> satirlar = Files.readAllLines(hedefDosya.toPath(), StandardCharsets.UTF_8);
            boolean herhangiBirSatirDegisti = false;

            for (int satirIndex = 0; satirIndex < satirlar.size(); satirIndex++) {
                String eski = satirlar.get(satirIndex);
                String yeni = karakterleriCevir(eski);

                if (!eski.equals(yeni)) {
                    satirlar.set(satirIndex, yeni);
                    System.out.println("Dosya: " + hedefDosya.getAbsolutePath()
                            + " - Satir " + (satirIndex + 1) + " degistirildi.");
                    herhangiBirSatirDegisti = true;
                }
            }

            if (herhangiBirSatirDegisti) {
                Files.write(hedefDosya.toPath(), satirlar, StandardCharsets.UTF_8);
            }
        } catch (IOException hata) {
            System.out.println("Hata: " + hata.getMessage());
        }
    }

    private static String karakterleriCevir(String satir) {
        String sonuc = satir;
        for (Map.Entry<String, String> kural : DEGISIM_TABLOSU.entrySet()) {
            sonuc = sonuc.replace(kural.getKey(), kural.getValue());
        }
        return sonuc;
    }

    public static void main(String[] args) {
        File ustDizin = new File(System.getProperty("user.dir")).getParentFile();
        agaciGez(ustDizin);
    }
}
