/** "Girisi Yasak" trafik levhasini geometrik sekillerle ciziyor. */
public class GirisYasaktirIsareti extends JPanel {

    private static final long serialVersionUID = 1L;

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);

        Point ortaNokta = new Point(getWidth() / 2, getHeight() / 2);

        int disCemberYaricapi = Math.min(getWidth() / 2, getHeight() / 2) - 5;
        int icCemberYaricapi = (int) (disCemberYaricapi * 0.9);
        int cubukUzunlugu = (int) (icCemberYaricapi * 1.4);
        int cubukKalinligi = (int) (icCemberYaricapi * 0.35);

        // Levhanin beyaz kenarligi
        tuval.setColor(Color.WHITE);
        tuval.fillOval(ortaNokta.x - disCemberYaricapi, ortaNokta.y - disCemberYaricapi,
                2 * disCemberYaricapi, 2 * disCemberYaricapi);

        // Kirmizi govde
        tuval.setColor(Color.RED);
        tuval.fillOval(ortaNokta.x - icCemberYaricapi, ortaNokta.y - icCemberYaricapi,
                icCemberYaricapi * 2, icCemberYaricapi * 2);

        // Ortadaki yatay beyaz cubuk
        tuval.setColor(Color.WHITE);
        tuval.fillRect(ortaNokta.x - cubukUzunlugu / 2, ortaNokta.y - cubukKalinligi / 2,
                cubukUzunlugu, cubukKalinligi);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            GirisYasaktirIsareti levha = new GirisYasaktirIsareti();
            levha.setBackground(Color.GREEN.darker());

