import javax.swing.*;
import java.awt.*;
import javax.swing.border.EmptyBorder;

/**
 * Bir cok Swing bilesenini (label, text field, combo box, checkbox,
 * button) tek bir dikey panelde bir araya getiren tanitim ekrani.
 */
public class SwingDemo {

    public static void main(String[] args) {
        JFrame anaPencere = new JFrame("Swing Demo");
        anaPencere.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        anaPencere.setSize(600, 600);
        anaPencere.setLocationRelativeTo(null);

        JPanel dikeyPanel = new JPanel();
        dikeyPanel.setLayout(new BoxLayout(dikeyPanel, BoxLayout.Y_AXIS));
        dikeyPanel.setBackground(new Color(240, 240, 240));

        JScrollPane kaydirmaAlani = new JScrollPane(dikeyPanel);

        JLabel bilgiEtiketi = new JLabel("Swing'e Hos Geldiniz!");
        bilgiEtiketi.setAlignmentX(Component.CENTER_ALIGNMENT);
        bilgiEtiketi.setFont(new Font("Arial", Font.BOLD, 18));
        bilgiEtiketi.setForeground(new Color(50, 50, 50));
        bilgiEtiketi.setBorder(new EmptyBorder(10, 0, 20, 0));

        JTextField mesajKutusu = new JTextField(15);
        mesajKutusu.setToolTipText("Bir mesaj yazin");
        mesajKutusu.setAlignmentX(Component.CENTER_ALIGNMENT);
        mesajKutusu.setFont(new Font("Arial", Font.PLAIN, 16));
        mesajKutusu.setBackground(Color.WHITE);
        mesajKutusu.setBorder(BorderFactory.createLineBorder(Color.GRAY, 1));

        String[] renkSecenekleri = {"Kirmizi", "Yesil", "Mavi", "Sari"};
        JComboBox<String> renkListesi = new JComboBox<>(renkSecenekleri);
        renkListesi.setToolTipText("Bir renk secin");
        renkListesi.setAlignmentX(Component.CENTER_ALIGNMENT);
        renkListesi.setFont(new Font("Arial", Font.PLAIN, 16));
        renkListesi.setBackground(new Color(255, 255, 255));
        renkListesi.setBorder(BorderFactory.createLineBorder(Color.GRAY, 1));

        JCheckBox gizlemeKutusu = new JCheckBox("Mesaji gizle");
        gizlemeKutusu.setToolTipText("Mesaji gizlemek icin tiklayin");
        gizlemeKutusu.setAlignmentX(Component.CENTER_ALIGNMENT);
        gizlemeKutusu.setFont(new Font("Arial", Font.PLAIN, 16));

        JButton eylemTusu = new JButton("Beni Tikla!");
        eylemTusu.setAlignmentX(Component.CENTER_ALIGNMENT);
        eylemTusu.setFont(new Font("Arial", Font.BOLD, 16));
        eylemTusu.setBackground(new Color(60, 179, 113));
        eylemTusu.setForeground(Color.WHITE);
        eylemTusu.setFocusPainted(false);
        eylemTusu.setBorder(BorderFactory.createRaisedBevelBorder());

        eylemTusu.addActionListener(e -> {
            String girilenMetin = mesajKutusu.getText();
            String secilenRenk = (String) renkListesi.getSelectedItem();
            boolean gizlensinMi = gizlemeKutusu.isSelected();

            if (gizlensinMi) {
                bilgiEtiketi.setText("Mesaj Gizlendi!");
            } else {
                bilgiEtiketi.setText("Girilen Mesaj: " + girilenMetin + " | Secilen Renk: " + secilenRenk);
            }
        });

        dikeyPanel.add(bilgiEtiketi);
        dikeyPanel.add(Box.createVerticalStrut(20));
        dikeyPanel.add(mesajKutusu);
        dikeyPanel.add(Box.createVerticalStrut(10));
        dikeyPanel.add(renkListesi);
        dikeyPanel.add(Box.createVerticalStrut(10));
        dikeyPanel.add(gizlemeKutusu);
        dikeyPanel.add(Box.createVerticalStrut(10));
        dikeyPanel.add(eylemTusu);

        anaPencere.add(kaydirmaAlani);
        anaPencere.setVisible(true);
    }
}
