/**
 * Demonstrates subclassing Thread directly (as opposed to Runnable),
 * with a tick counter and a cooperative stop flag.
 */
public class ThreadOrnegi extends Thread {

    private final String label;
    private final int intervalMillis;
    private volatile boolean running = true;

    public ThreadOrnegi(String label, int intervalMillis) {
        this.label = label;
        this.intervalMillis = intervalMillis;
    }

    @Override
    public void run() {
        int tick = 0;
        while (running) {
            System.out.println(Thread.currentThread().getName() + ": " + label + " [" + tick + "]");
            try {
                Thread.sleep(intervalMillis);
            } catch (InterruptedException interrupted) {
                System.out.println(Thread.currentThread().getName() + " kesildi.");
                return;
            }
            tick++;
        }
        System.out.println(Thread.currentThread().getName() + " durduruldu.");
    }

    public void requestStop() {
        running = false;
    }

    public static void main(String[] args) {
        ThreadOrnegi workerA = new ThreadOrnegi("ali", 1000);
        Thread t1 = new Thread(workerA, "Thread-1");

        ThreadOrnegi workerB = new ThreadOrnegi("veli", 2000);
        Thread t2 = new Thread(workerB, "Thread-2");

        ThreadOrnegi workerC = new ThreadOrnegi("ayse", 3000);
        Thread t3 = new Thread(workerC, "Thread-3");

        t1.start();
        t2.start();
        t3.start();

        // Keep the main thread busy while the workers run in parallel
        for (int step = 0; step < 5; step++) {
            System.out.println("Ana thread is yapiyor: " + step);
            pause(500);
        }

        pause(10000);

        System.out.println("Tum thread'ler durduruluyor...");
        workerA.requestStop();
        workerB.requestStop();
        workerC.requestStop();

        for (Thread t : new Thread[] { t1, t2, t3 }) {
            try {
                t.join();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        System.out.println("Program tamamlandi.");
    }

    private static void pause(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
