package example;

import java.io.BufferedReader;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.ServerSocket;
import java.net.Socket;

// One thread per connected client; simply echoes back whatever it reads
class ConnectionWorker extends Thread {
    private DataInputStream fromClient;
    private DataOutputStream toClient;
    private final Socket clientSocket;
    private final BufferedReader console = new BufferedReader(new InputStreamReader(System.in));

    public ConnectionWorker(Socket clientSocket) {
        this.clientSocket = clientSocket;
        try {
            fromClient = new DataInputStream(clientSocket.getInputStream());
            toClient = new DataOutputStream(clientSocket.getOutputStream());
        } catch (IOException e) {
            e.printStackTrace();
            System.out.println("Istemci baglantisi olusturulurken hata meydana geldi: " + e.getMessage());
        }
    }

    @Override
    public void run() {
        try {
            String received = "";
            while (!received.equals("stop")) {
                received = fromClient.readUTF();
                System.out.println("Istemciden alinan mesaj: " + received);
                toClient.writeUTF(received);
                toClient.flush();
            }
        } catch (IOException e) {
            System.out.println("Istemci ile baglanti koptu: " + e.getMessage());
        } finally {
            try {
                clientSocket.close();
                System.out.println("Istemci soketi kapatildi.");
            } catch (IOException e) {
                System.out.println("Soket kapatilirken hata meydana geldi: " + e.getMessage());
            }
        }
    }
}

/**
 * Accepts connections forever, spinning up a ConnectionWorker thread
 * for each client that connects.
 */
public class Server {

    private static final int PORT = 4444;

    public static void main(String[] args) throws IOException {
        ServerSocket listener = new ServerSocket(PORT);
        System.out.println("Sunucu baslatildi ve baglanti bekleniyor...");

        while (true) {
            Socket clientSocket = null;
            try {
                clientSocket = listener.accept();
                System.out.println("Yeni bir istemci baglandi: " + clientSocket);

                Thread worker = new ConnectionWorker(clientSocket);
                worker.start();

            } catch (Exception e) {
                System.out.println("Baglanti sirasinda hata meydana geldi: " + e.getMessage());
                if (clientSocket != null && !clientSocket.isClosed()) {
                    clientSocket.close();
                    System.out.println("Baglanti hatali soket kapatildi.");
                }
                listener.close();
                e.printStackTrace();
                break;
            }
        }
    }
}
