package sqlite;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

/*
 * Walkthrough of basic SQLite operations from Java:
 *
 * - open a connection
 * - create a table
 * - insert, update, and delete rows
 * - list everything currently in the table
 */

public class SQLiteDemo {

    private static final String DB_URL = "jdbc:sqlite:test.db";

    public static void main(String[] args) {

        try (Connection db = DriverManager.getConnection(DB_URL);
             Statement stmt = db.createStatement()) {

            String createTable = "CREATE TABLE IF NOT EXISTS users (\n"
                    + " id INTEGER PRIMARY KEY,\n"
                    + " first_name TEXT NOT NULL,\n"
                    + " last_name TEXT NOT NULL,\n"
                    + " age INTEGER NOT NULL\n"
                    + ");";
            stmt.execute(createTable);
            System.out.println("Tablo basariyla olusturuldu");

            addPerson(db, "John", "Doe", 30);
            System.out.println("Kayit basariyla eklendi");

            addPerson(db, "Mike", "Tyson", 40);
            System.out.println("Kayit basariyla eklendi");

            listPeople(db);
            System.out.println("Tablo basariyla listelendi");

            editPerson(db, "John", "Smith", 35);
            System.out.println("Kayit basariyla guncellendi");

            listPeople(db);
            System.out.println("Tablo basariyla listelendi");

            removePerson(db, "John");
            System.out.println("Kayit basariyla silindi");

            listPeople(db);
            System.out.println("Tablo basariyla listelendi");

        } catch (SQLException e) {
            System.out.println(e.getMessage());
        }
    }

    public static void addPerson(Connection db, String firstName, String lastName, int age) throws SQLException {
        String sql = "INSERT INTO users(first_name, last_name, age) VALUES(?, ?, ?)";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, firstName);
            stmt.setString(2, lastName);
            stmt.setInt(3, age);
            stmt.executeUpdate();
        }
    }

    public static void editPerson(Connection db, String firstName, String lastName, int age) throws SQLException {
        String sql = "UPDATE users SET last_name = ?, age = ? WHERE first_name = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, lastName);
            stmt.setInt(2, age);
            stmt.setString(3, firstName);
            stmt.executeUpdate();
        }
    }

    public static void listPeople(Connection db) throws SQLException {
        String sql = "SELECT id, first_name, last_name, age FROM users";
        try (Statement stmt = db.createStatement()) {
            ResultSet rows = stmt.executeQuery(sql);
            while (rows.next()) {
                System.out.println(rows.getInt("id") + "\t"
                        + rows.getString("first_name") + "\t"
                        + rows.getString("last_name") + "\t"
                        + rows.getInt("age"));
            }
        }
    }

    public static void removePerson(Connection db, String firstName) throws SQLException {
        String sql = "DELETE FROM users WHERE first_name = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, firstName);
            stmt.executeUpdate();
        }
    }
}
