/**
 * Simple bank account model with credit/debit/transfer operations.
 */
public class Account {
    private String accountId;
    private String ownerName;
    private int balance;

    public Account(String accountId, String ownerName) {
        this(accountId, ownerName, 0);
    }

    public Account(String accountId, String ownerName, int balance) {
        this.accountId = accountId;
        this.ownerName = ownerName;
        this.balance = balance;
    }

    public String getID() {
        return accountId;
    }

    public void setID(String accountId) {
        this.accountId = accountId;
    }

    public String getName() {
        return ownerName;
    }

    public void setName(String ownerName) {
        this.ownerName = ownerName;
    }

    public int getBalance() {
        return balance;
    }

    public void setBalance(int balance) {
        this.balance = balance;
    }

    public int credit(int amount) {
        balance = balance + amount;
        return balance;
    }

    public int debit(int amount) {
        boolean enoughFunds = amount <= balance;
        if (enoughFunds) {
            balance -= amount;
        } else {
            System.out.println("Amount exceeded balance");
        }
        return balance;
    }

    public int transferTo(Account destination, int amount) {
        if (amount > balance) {
            System.out.println("Amount exceeded balance");
            return balance;
        }
        balance -= amount;
        destination.balance += amount;
        return balance;
    }

    @Override
    public String toString() {
        return "Account[id=" + accountId + ",name=" + ownerName + ",balance=" + balance + ']';
    }
}

class TestAccount {
    public static void main(String[] args) {
        Account a1 = new Account("A101", "Tan Ah Teck", 88);
        System.out.println(a1);
        Account a2 = new Account("A102", "Kumar");
        System.out.println(a2);

        System.out.println("ID: " + a1.getID());
        System.out.println("Name: " + a1.getName());
        System.out.println("Balance: " + a1.getBalance());

        a1.credit(100);
        System.out.println(a1);
        a1.debit(50);
        System.out.println(a1);
        a1.debit(500);
        System.out.println(a1);

        a1.transferTo(a2, 100);
        System.out.println(a1);
        System.out.println(a2);
    }
}
