package GUI;

import DTO.Item;
import DTO.Painting;
import DTO.Statue;
import DTO.Vase;
import java.util.Scanner;

/**
 * Console menu for creating and displaying antique items.
 */
public class AntiqueShop {

    public static void main(String[] args) {
        Item current = null;
        int choice;
        Scanner scanner = new Scanner(System.in);
        do {
            System.out.println("1. Create a Vase:");
            System.out.println("2. Create a Statue:");
            System.out.println("3. Create a Painting:");
            System.out.println("4. Display the Item:");
            System.out.print("Input a choice: ");
            choice = scanner.nextInt();
            scanner.nextLine();

            if (choice == 1) {
                Vase vase = new Vase();
                vase.inputVase();
                current = vase;
            } else if (choice == 2) {
                Statue statue = new Statue();
                statue.inputStatue();
                current = statue;
            } else if (choice == 3) {
                Painting painting = new Painting();
                painting.inputPainting();
                current = painting;
            } else if (choice == 4) {
                if (current == null) {
                    System.out.println("you need to create an object");
                } else if (current instanceof Vase) {
                    ((Vase) current).outputVase();
                } else if (current instanceof Statue) {
                    ((Statue) current).outputStatue();
                } else if (current instanceof Painting) {
                    ((Painting) current).outputPainting();
                }
            }
        } while (choice <= 4);
    }
}
