package LineSub;

/**
 * A line segment that extends Point to reuse the "begin" coordinate,
 * while composing a second Point for the "end" coordinate.
 */
public class LineSub extends Point {

    private Point endPoint;

    public LineSub(Point begin, Point end) {
        super(begin.getX(), begin.getY());
        this.endPoint = end;
    }

    public LineSub(int beginX, int beginY, int endX, int endY) {
        super(beginX, beginY);
        this.endPoint = new Point(endX, endY);
    }

    @Override
    public String toString() {
        return "LineSub[begin=" + super.toString() + ",end=" + endPoint + ']';
    }

    public Point getBegin() {
        return new Point(getX(), getY());
    }

    public Point getEnd() {
        return endPoint;
    }

    public void setBegin(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEnd(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getBeginX() {
        return getX();
    }

    public int getBeginY() {
        return getY();
    }

    public int getEndX() {
        return endPoint.getX();
    }

    public int getEndY() {
        return endPoint.getY();
    }

    public void setBeginX(int beginX) {
        setX(beginX);
    }

    public void setBeginY(int beginY) {
        setY(beginY);
    }

    public void setBeginXY(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEndX(int endX) {
        endPoint.setX(endX);
    }

    public void setEndY(int endY) {
        endPoint.setY(endY);
    }

    public void setEndXY(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getLength() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        double distance = Math.sqrt(dx * dx + dy * dy);
        return (int) distance;
    }

    public double getGradient() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        return Math.atan2(dy, dx);
    }
}

