        BigDog bigDog2 = (BigDog)animal3;
        Dog dog3 = (Dog)animal3;
        // Cat cat2 = (Cat)animal2;        // Error!!! Dog cannot be cast to Cat !

        dog2.greeting(dog3);
        dog3.greeting(dog2);
        dog2.greeting(bigDog2);
        bigDog2.greeting(dog2);
        bigDog2.greeting(bigDog1);

        bigDog1.greeting(bigDog2);
    }
}
