package workshop6;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;

/**
 * A managed list of students with CRUD and sorting operations.
 */
public class StudentList extends ArrayList<Student> {

    public StudentList() {
        super();
    }

    public Student search(String code) {
        String target = code.trim().toUpperCase();
        for (int i = 0; i < size(); i++) {
            if (get(i).getCode().equals(target)) {
                return get(i);
            }
        }
        return null;
    }

    private boolean isCodeDuplicated(String code) {
        return search(code.trim().toUpperCase()) != null;
    }

    public void addStudent() {
        String newCode;
        boolean codeDuplicated;
        do {
            newCode = Inputter.inputPattern("St. code S000: ", "[sS][\\d]{3}");
            codeDuplicated = isCodeDuplicated(newCode);
            if (codeDuplicated) {
                System.out.println("Code is duplicated");
            }
        } while (codeDuplicated);
        String newName = Inputter.inputNonBlankStr("Name of new student: ").toUpperCase();
        int newMark = Inputter.inputInt("Mark: ", 0, 10);
        add(new Student(newCode, newName, newMark));
        System.out.println("Student " + newCode + " has been added");
    }

    public void searchStudent() {
        if (isEmpty()) {
            System.out.println("Empty list. No search can be performend!");
            return;
        }
        String code = Inputter.inputStr("Input student code for search: ");
        Student student = search(code);
        if (student == null) {
            System.out.println("Student " + code + " doesn't existed!");
        } else {
            System.out.println("Founđ: " + student);
        }
    }

    public void updateStudent() {
        if (isEmpty()) {
            System.out.println("Empty list. No update can be performend!");
            return;
        }
        String code = Inputter.inputStr("Input code of update student: ");
        Student student = search(code);
        if (student == null) {
            System.out.println("Student " + code + " doesn't existed!");
            return;
        }
        String newName = Inputter.inputNonBlankStr("Old name: " + student.getName() + ", new name: ");
        student.setName(newName);
        int newMark = Inputter.inputInt("Old mark: " + student.getMark() + ", new mark: ", 0, 10);
        student.setMark(newMark);
        System.out.println("Student " + code + " has bean updated.");
    }

    public void removeStudent() {
        if (isEmpty()) {
            System.out.println("Empty list. No remove can be performend!");
            return;
        }
        String code = Inputter.inputStr("Input code of remove student: ");
        Student student = search(code);
        if (student == null) {
            System.out.println("Student " + code + " doesn't existed!");
        } else {
            remove(student);
            System.out.println("Student " + code + " has been removed.");
        }
    }

    public void printAll() {
        if (isEmpty()) {
            System.out.println("Empty list!");
            return;
        }
        System.out.println("Student list:");
        for (Student student : this) {
            System.out.println(student);
        }
        System.out.println("Total: " + size() + " student(s).");
    }

    public void sortByMarkDecresing() {
        Collections.sort(this);
    }

    public void sortByMarkInCresing() {
        Collections.sort(this, new Comparator<Student>() {
            @Override
            public int compare(Student a, Student b) {
                if (a.getMark() > b.getMark()) {
                    return 1;
                }
                return a.getMark() == b.getMark() ? a.getName().compareTo(b.getName()) : -1;
            }
        });
    }
}
